import getColor from '@helpers/colorsHelper';

export const getWorkoutTypeColor = (id: number) => {
  switch (id) {
    case 1: //поход
      return '#fa9200';
    case 2: //ski
      return '#00ddfc';
    case 3: //run
      return '#ec2a2a';
    case 4: //bike
      return '#00aff2';
    case 5: //walk
      return '#ffc634';
    case 6: //kayak
      return '#00bfe8';
    default:
      return getColor(1 + id + id);
  }
};

export const tryDefineWorkoutTypeByKeyword = (keyword: string): number | null => {
  const kw = keyword.toLowerCase();

  if (
    ['hiking', 'tracking', 'backpack', 'поход', 'трекинг', 'треккинг'].some((s) => kw.includes(s))
  )
    return 1; //поход

  if (['ski', 'лыж'].some((s) => kw.includes(s))) return 2; //ski
  if (['run', 'бег'].some((s) => kw.includes(s))) return 3; //run
  if (['bike', 'вел'].some((s) => kw.includes(s))) return 4; //bike
  if (['walk', 'прогул', 'ходь'].some((s) => kw.includes(s))) return 5; //walk
  if (['kayak', 'сплав'].some((s) => kw.includes(s))) return 6; //kayak

  return null;
};
